SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DEKİ DOĞAL GÖLLERİN OLUŞUM KÖKENLERİNE GÖRE TASNİFİ</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">A) YERLİ KAYA (ÇANAK) GÖLLERİ</text>\n  <rect x="32" y="78" width="296" height="36" rx="5" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="42" y="94" font-size="10.5" font-weight="bold" fill="#1d4ed8">1. Tektonik Göller:</text>\n  <text x="42" y="108" font-size="10" fill="#334155">Tuz, Beyşehir, Eğirdir, İznik, Manyas, Ulubat, Sapanca, Hazar</text>\n  <rect x="32" y="120" width="296" height="36" rx="5" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="42" y="136" font-size="10.5" font-weight="bold" fill="#1d4ed8">2. Karstik Göller:</text>\n  <text x="42" y="150" font-size="10" fill="#334155">Salda, Kestel, Avlan, Suğla, Kızören Obruk Gölü</text>\n  <rect x="32" y="162" width="296" height="34" rx="5" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="42" y="177" font-size="10.5" font-weight="bold" fill="#1d4ed8">3. Volkanik Göller:</text>\n  <text x="42" y="190" font-size="10" fill="#334155">Nemrut Kalderası, Meke Maarı, Acıgöl, Isparta Gölcük</text>\n  <rect x="32" y="202" width="296" height="32" rx="5" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="42" y="216" font-size="10.5" font-weight="bold" fill="#1d4ed8">4. Buzul (Sirk) Gölleri:</text>\n  <text x="42" y="228" font-size="10" fill="#334155">Kaçkar, Cilo (Buzul), Uludağ (Kilimli, Aynalı), Aladağlar</text>\n\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">B) DOĞAL SET GÖLLERİ</text>\n  <rect x="372" y="78" width="296" height="36" rx="5" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="382" y="94" font-size="10.5" font-weight="bold" fill="#15803d">1. Volkanik (Lav) Set:</text>\n  <text x="382" y="108" font-size="10" fill="#334155">Van Gölü (Karma), Erçek, Nazik, Haçlı, Çıldır, Balık</text>\n  <rect x="372" y="120" width="296" height="36" rx="5" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="382" y="136" font-size="10.5" font-weight="bold" fill="#15803d">2. Heyelan Set:</text>\n  <text x="382" y="150" font-size="10" fill="#334155">Tortum, Sera, Abant, Yedigöller, Boraboy, Zinav</text>\n  <rect x="372" y="162" width="296" height="34" rx="5" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="382" y="177" font-size="10.5" font-weight="bold" fill="#15803d">3. Alüvyal Set:</text>\n  <text x="382" y="190" font-size="10" fill="#334155">Mogan, Eymir, Bafa (Çamiçi), Köyceğiz, Marmara</text>\n  <rect x="372" y="202" width="296" height="32" rx="5" fill="#ffffff" stroke="#22c55e" stroke-width="1.2"/>\n  <text x="382" y="216" font-size="10.5" font-weight="bold" fill="#15803d">4. Kıyı Set (Lagün):</text>\n  <text x="382" y="228" font-size="10" fill="#334155">Büyükçekmece, Küçükçekmece, Terkos (Durusu), Akyatan</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'NİN AKARSU HAVZALARI VE SINIR AŞAN SULARIMIZ</text>\n  <rect x="20" y="45" width="210" height="190" rx="9" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">Karadeniz &amp; Marmara</text>\n  <text x="32" y="92" font-size="10.5" fill="#334155">• Kızılırmak (En uzun iç nehir)</text>\n  <text x="32" y="112" font-size="10.5" fill="#334155">• Yeşilırmak (Çarşamba Deltası)</text>\n  <text x="32" y="132" font-size="10.5" fill="#334155">• Sakarya, Filyos, Bartın Çayı</text>\n  <text x="32" y="152" font-size="10.5" fill="#334155">• Çoruh (Gürcistan\'dan dökülür)</text>\n  <text x="32" y="176" font-size="10.5" font-weight="bold" fill="#0c4a6e">Marmara: Susurluk Çayı</text>\n  <text x="32" y="198" font-size="10" fill="#475569">Ege: Meriç (Yunanistan sınırı),</text>\n  <text x="32" y="213" font-size="10" fill="#475569">Bakırçay, Gediz, K. ve B. Menderes</text>\n\n  <rect x="245" y="45" width="210" height="190" rx="9" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Akdeniz &amp; Basra Havzası</text>\n  <text x="257" y="92" font-size="10.5" fill="#334155">• Seyhan ve Ceyhan (Çukurova)</text>\n  <text x="257" y="112" font-size="10.5" fill="#334155">• Göksu (Silifke Deltası)</text>\n  <text x="257" y="132" font-size="10.5" fill="#334155">• Manavgat, Köprüçay, Aksu, Dalaman</text>\n  <text x="257" y="152" font-size="10.5" fill="#334155">• Asi (Lübnan-Suriye\'den gelir)</text>\n  <rect x="257" y="168" width="186" height="54" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="350" y="186" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Basra Körfezi (Dışa Akışlı):</text>\n  <text x="350" y="203" text-anchor="middle" font-size="10" fill="#334155">Fırat ve Dicle Nehirleri</text>\n\n  <rect x="470" y="45" width="210" height="190" rx="9" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">Kapalı Havzalarımız</text>\n  <text x="482" y="92" font-size="10.5" fill="#334155">• Tuz Gölü / Konya Kapalı Havzası</text>\n  <text x="482" y="112" font-size="10.5" fill="#334155">• Van Gölü Kapalı Havzası</text>\n  <text x="482" y="132" font-size="10.5" fill="#334155">• Göller Yöresi (Burdur, Acıgöl)</text>\n  <text x="482" y="152" font-size="10.5" fill="#334155">• Akarçay (Afyon) Havzası</text>\n  <rect x="482" y="168" width="186" height="54" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.2"/>\n  <text x="575" y="186" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">Hazar Gölü Kapalı Havzası:</text>\n  <text x="575" y="203" text-anchor="middle" font-size="10" fill="#334155">Aras ve Kura Nehirleri</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKİYE\'DE YER ALTI KAYNAKLARI VE BAŞLICA BARAJ GÖLLERİ</text>\n  <rect x="25" y="48" width="310" height="182" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">1. Türkiye\'nin Yer Altı Su Kaynakları</text>\n  <text x="40" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Fay Kaynakları:</tspan> KAF, DAF ve BAF hatları boyunca</text>\n  <text x="48" y="113" font-size="10" fill="#475569">yaygındır (Afyon, Bursa, Denizli, Aydın; jeotermal).</text>\n  <text x="40" y="136" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Karstik Kaynaklar (Voklüz):</tspan> Akdeniz ve Batı</text>\n  <text x="48" y="151" font-size="10" fill="#475569">Toroslar\'da yaygındır; suları soğuk ve kireçlidir.</text>\n  <text x="40" y="174" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Artezyen Kaynaklar:</tspan> Konya, Ergene, Bursa ve</text>\n  <text x="48" y="189" font-size="10" fill="#475569">Çukurova\'da sondajla çıkarılır; aşırı çekim obruk yapar.</text>\n  <text x="40" y="212" font-size="10.5" font-weight="bold" fill="#b91c1c">• Gayzer: Aktif volkan olmadığı için Türkiye\'de yoktur.</text>\n\n  <rect x="365" y="48" width="310" height="182" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Akarsularımız ve Önemli Barajlar</text>\n  <text x="380" y="98" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Fırat Nehri:</tspan> Atatürk, Keban, Karakaya, Birecik</text>\n  <text x="380" y="120" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Dicle Nehri:</tspan> Ilısu (Veysel Eroğlu), Kralkızı, Devegeçidi</text>\n  <text x="380" y="142" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Çoruh Nehri:</tspan> Yusufeli, Deriner, Borçka, Muratlı</text>\n  <text x="380" y="164" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Kızılırmak:</tspan> Hirfanlı, Altınkaya, Kesikköprü</text>\n  <text x="380" y="186" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Yeşilırmak:</tspan> Hasan Uğurlu, Suat Uğurlu, Almus</text>\n  <text x="380" y="208" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#166534">Seyhan ve Ceyhan:</tspan> Seyhan, Çatalan, Aslantaş</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
